import { MakeLogicType, actions, kea, key, path, props, reducers } from 'kea'
import { beforeUnload, router } from 'kea-router'

export interface UnsavedSettingsLogicProps {
    /** Identifies the settings section, so two sections on one page track their edits apart. */
    sectionId: string
    message: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface unsavedSettingsLogicValues {
    hasUnsavedChanges: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface unsavedSettingsLogicActions {
    setHasUnsavedChanges: (hasUnsavedChanges: boolean) => {
        hasUnsavedChanges: boolean
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface unsavedSettingsLogicMeta {
    key: string
}

export type unsavedSettingsLogicType = MakeLogicType<
    unsavedSettingsLogicValues,
    unsavedSettingsLogicActions,
    UnsavedSettingsLogicProps,
    unsavedSettingsLogicMeta
>

// Switches and selects on this settings page save themselves on change, so a typed value in a
// Save-button section reads as saved and is lost on navigation unless something asks first.
export const unsavedSettingsLogic = kea<unsavedSettingsLogicType>([
    props({} as UnsavedSettingsLogicProps),
    key((props) => props.sectionId),
    path((key) => ['products', 'workflows', 'scenes', 'settings', 'unsavedSettingsLogic', key]),
    actions({
        setHasUnsavedChanges: (hasUnsavedChanges: boolean) => ({ hasUnsavedChanges }),
    }),
    reducers({
        hasUnsavedChanges: [
            false,
            {
                setHasUnsavedChanges: (_, { hasUnsavedChanges }) => hasUnsavedChanges,
            },
        ],
    }),
    beforeUnload(({ values, props, actions }) => ({
        enabled: (newLocation) => {
            if (!values.hasUnsavedChanges) {
                return false
            }
            // A heading's link icon only sets the hash. The section stays mounted and still
            // dirty, so prompting there would clear the flag while the edits are still at risk.
            return !newLocation || newLocation.pathname !== router.values.location.pathname
        },
        message: props.message,
        onConfirm: () => {
            actions.setHasUnsavedChanges(false)
        },
    })),
])
